CREATE TABLE share_grant (id UUID PRIMARY KEY DEFAULT uuid_v7(),issuer_id UUID NOT NULL,target_type VARCHAR(64) NOT NULL,target_id UUID NOT NULL,grantee_type VARCHAR(24) NOT NULL,grantee_id UUID,capabilities VARCHAR(2000) NOT NULL,token_digest VARCHAR(128),expires_at TIMESTAMPTZ,status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,updated_at TIMESTAMPTZ NOT NULL DEFAULT current_timestamp,version BIGINT NOT NULL DEFAULT 0,CHECK(grantee_type IN ('USER','LINK_TOKEN','GUEST_SESSION')),CHECK(status IN ('ACTIVE','REVOKED','EXPIRED')),CHECK(version>=0));
CREATE UNIQUE INDEX uk_share_token_digest ON share_grant(token_digest) WHERE token_digest IS NOT NULL;
CREATE INDEX idx_share_target ON share_grant(target_type,target_id,status);
